    var cr = { p: [], base: [], m: [] };                           // splash crowns
    var spr = { p: [], x: [], m: [] };                             // boiling crowns, mist, sparkles
    var cols = [];
    function bez(p0, c, p1, t) { return [0, 1, 2].map(function (k) { return (1 - t) * (1 - t) * p0[k] + 2 * (1 - t) * t * c[k] + t * t * p1[k]; }); }
